-- Passage rg4-main-idea-summary-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('84049490-22f8-50c5-b4ef-aab2f17123ec', 'rg4-main-idea-summary-p06', (select id from public.skills where slug = 'read-g4-main-idea-summary'), null,
        '3-5', $q$The Art of Shadow Puppets$q$, $q$Shadow puppetry is one of the oldest kinds of storytelling. People in many parts of the world have used it for hundreds of years. All it needs is a light, a screen, and some puppets.

The puppets are flat cutouts. Long ago, makers often cut them from dried animal skin. Today, many are made from stiff paper or cardboard. Tiny holes and cut shapes let light shine through to show eyes, clothing patterns, and other details. Thin sticks are attached so the puppeteer can move the arms and legs.

For a show, a bright light is placed behind a white cloth screen. The puppeteer holds the puppets between the light and the screen. The audience sits on the other side. They do not see the puppets themselves, only their dark shadows.

Puppeteers use clever tricks. Moving a puppet closer to the light makes its shadow grow larger. Moving it toward the screen makes the shadow smaller and sharper. Music and voices help bring each story to life.

Because the tools are simple, almost anyone can try shadow puppetry. Students can make puppets in art class and put on a show with a flashlight and a bedsheet.$q$, 'draft')
