insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('d5dbbaea-becc-582f-af9a-04b94e5e620e', 'rg4-text-structure-p01', (select id from public.skills where slug = 'read-g4-text-structure'), null,
        '3-5', $q$From Tree to Table: Making Maple Syrup$q$, $q$Maple syrup starts deep inside a tree. Making it takes patience and many steps. Farmers follow the same steps every spring.

First, the farmer waits for the right weather. Sap flows best when nights are below freezing and days are warm. This usually happens in late winter.

Next, the farmer drills a small hole in each maple tree. A little spout called a tap goes into the hole. A bucket or a tube hangs below it to catch the sap.

Then the sap drips out, drop by drop. Sap looks like water and tastes only a little sweet. The farmer collects it every day.

After that, the sap is boiled in a wide pan for many hours. The water turns into steam and floats away. The sap slowly gets thicker, darker, and sweeter.

Finally, the syrup is strained and poured into bottles. It takes about forty buckets of sap to make just one bucket of syrup!$q$, 'draft')
