insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('3fc6bbe0-35ac-56ac-a5dc-0ff8ee458b7d', 'rg4-theme-summary-p04', (select id from public.skills where slug = 'read-g4-theme-summary'), null,
        '3-5', $q$The Last Ten Seconds$q$, $q$Rafael was the best shooter on the Comets, his basketball team. In every game, he wanted the ball. When he got it, he shot.

Coach Bianca had noticed. At practice one Tuesday, she tried a new drill. "Today, nobody can shoot until the ball has been passed three times," she said. Rafael groaned. Passing felt slow.

During the drill, he saw things he had missed before. Mei was quick at cutting toward the basket. Tobias could see the whole court and always knew where to throw. When the ball moved fast, someone was almost always open.

On Saturday, the Comets played the Hornets. With ten seconds left, the score was tied. Rafael caught the ball near the top of the key. Two Hornets rushed toward him, waving their arms.

Out of the corner of his eye, Rafael saw Mei slip behind them. She was wide open under the basket. For a moment he wanted to take the shot himself. Then he bounced the ball to Mei. She laid it in just as the buzzer sounded.

The team crowded around Mei, cheering. Then Mei pointed at Rafael. "Great pass!" she shouted.

Rafael grinned. He had not scored the winning basket, but he felt just as happy as if he had. Maybe even happier.$q$, 'draft')
