-- Passage rg4-theme-summary-p07
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('1b581b42-04f5-5c12-86b9-cbf174f5c5e0', 'rg4-theme-summary-p07', (select id from public.skills where slug = 'read-g4-theme-summary'), null,
        '3-5', $q$Snow on Maple Street$q$, $q$The snow came down all night and day.
It hid the cars. It hid the way.
Old Mr. Petrov, next door to me,
could barely see past his own front tree.

I didn't wait for someone to ask.
I grabbed my shovel for the task.
I scraped his steps and salted, too,
until the path was clear and new.

Next morning, on my porch, I found
a jar of cookies, warm and round,
and a note that said, in shaky hand,
"You made my day. You're simply grand."

Now when it snows, it's not just me.
The kids from down the block agree.
We clear the walks from end to end,
and every neighbor is a friend.$q$, 'draft')
