-- Passage rg4-word-parts-p05
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('87913974-cff1-52fc-beb0-5ddf5c00a8c3', 'rg4-word-parts-p05', (select id from public.skills where slug = 'read-g4-word-parts'), null,
        '3-5', $q$The Missing Library Book$q$, $q$Hana could not find her library book anywhere. She was sure she had put it in her backpack. Now it had disappeared.

She checked under her bed and behind the couch. She looked in the kitchen, where she sometimes read during breakfast. Her little brother Leo said she must have misplaced it at school.

"I did not misplace it," Hana said. "I always keep it in the same pocket." But she began to feel doubtful. Maybe she had not been so careful after all. The book was due on Monday, and she did not want to let down Mr. Reyes, the librarian.

On Sunday, Hana retraced her steps from Friday afternoon. She remembered stopping at the park on the way home. She had sat on a bench to read the last chapter.

Hana and her mother walked to the park. A park worker said someone had found a book and taken it to the office. Hana hurried there and spotted her book on a shelf, safe and dry. She was so thankful that she wrote the worker a note.

On Monday, Hana returned the book and told Mr. Reyes the whole story. He laughed and said it was the most traveled book in the library.$q$, 'draft')
