-- Passage rg4-word-parts-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('41a71ab8-4fe3-542d-b83c-17d5b1515f9e', 'rg4-word-parts-p06', (select id from public.skills where slug = 'read-g4-word-parts'), null,
        '3-5', $q$Talking Across the Miles$q$, $q$Today, you can talk to a friend in another city just by tapping a screen. About 150 years ago, that seemed almost like magic.

Before the telephone, many people used the telegraph. A telegraph sent messages along a wire as clicks of electricity. A trained operator tapped out a code of short and long signals. Another operator, far away, listened to the clicks and wrote down the words.

Then inventors built the first telephones. These were large wooden boxes. Callers had to shout into them. Calls were often unclear, and voices sounded crackly. Still, people could hear a real voice from many miles away.

Later came television. It sent moving pictures and sound through the air. Families gathered in the living room to watch the news together. For many people, it felt like the world had suddenly become smaller.

Now these inventions are packed into one small device. A phone can make calls, send messages, and play videos. It is hard to imagine life without it. Still, some families say a few unplugged hours each week are a useful break.$q$, 'draft')
